#include <map>
#include <string>
#include <iostream>

int main() {
    std::map<std::string, int> scores;

    // 1. Insertion via subscript (key 'Alice' inserted, value default initialized to 0)
    scores["Alice"] = 10;

    // 2. Lookup (no insertion)
    scores["Alice"] += 5; 

    // 3. Insertion of a new key 'Bob'
    // If int was a custom class, its default constructor would be called.
    int bob_score = scores["Bob"]; 

    std::cout << scores.size() << " elements." << std::endl;
    // Output: 2 elements.
}
